    \centering
\includegraphics[width=0.47\textwidth]{figures/TEKG_example.png}
  \caption{An example TKG (left) and the corresponding TEKG (right). The first row are the original versions, and the second row are the enhanced versions.}
  \label{fig:1}
\end{figure}

